<template><div><div class="page-head"><div><h1>Clients</h1><p>Manage customer accounts, credit limits and history.</p></div><button class="btn btn-primary" @click="openCreate">+ New client</button></div><div class="card mb-4 p-4"><div class="flex flex-col gap-3 md:flex-row"><input v-model="search" @keyup.enter="load" class="input md:max-w-sm" placeholder="Search clients…"><button class="btn btn-soft md:w-auto" @click="load">Search</button></div></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>Client</th><th>Contact</th><th>Number</th><th>Credit limit</th><th>Balance</th><th>Status</th><th class="text-right">Actions</th></tr></thead><tbody><tr v-for="c in clients" :key="c.id"><td><RouterLink :to="`/clients/${c.id}`" class="font-bold text-indigo-600 hover:underline">{{c.name}}</RouterLink><div class="text-[10px] text-slate-400">{{c.email||'No email'}}</div></td><td>{{c.phone||'—'}}</td><td>{{c.client_number}}</td><td>{{money(c.credit_limit)}}</td><td>{{money(Number(c.opening_balance||0)+Number(c.outstanding_balance||0))}}</td><td><StatusBadge :value="c.is_active"/></td><td><div class="flex justify-end gap-2"><button class="btn btn-soft" @click="edit(c)">Edit</button><button class="btn btn-danger" @click="remove(c)">Delete</button></div></td></tr><tr v-if="!clients.length"><td colspan="7"><div class="empty">No clients found.</div></td></tr></tbody></table></div><AppModal :open="open" :title="editing?'Edit client':'New client'" subtitle="Keep customer details and credit terms accurate." @close="open=false"><form @submit.prevent="save" class="grid grid-cols-1 gap-4 md:grid-cols-2"><div class="md:col-span-2"><label class="label">Business / client name *</label><input v-model="form.name" class="input" required></div><div><label class="label">Phone</label><input v-model="form.phone" class="input"></div><div><label class="label">Email</label><input v-model="form.email" class="input" type="email"></div><div><label class="label">Contact person</label><input v-model="form.contact_person" class="input"></div><div><label class="label">City</label><input v-model="form.city" class="input"></div><div><label class="label">TIN</label><input v-model="form.tin" class="input"></div><div><label class="label">VRN</label><input v-model="form.vrn" class="input"></div><div><label class="label">Credit limit</label><MoneyInput v-model="form.credit_limit" :min="0" /></div><div><label class="label">Credit days</label><input v-model.number="form.credit_days" class="input" type="number" min="0"></div><div class="md:col-span-2"><label class="label">Address</label><input v-model="form.address" class="input"></div><label class="md:col-span-2 flex items-center gap-2 text-xs font-semibold"><input v-model="form.is_active" type="checkbox"> Active client</label><div class="md:col-span-2"><label class="label">Notes</label><textarea v-model="form.notes" class="input min-h-24"></textarea></div><div class="md:col-span-2 flex justify-end gap-2 border-t border-slate-100 pt-4"><button type="button" class="btn btn-soft" @click="open=false">Cancel</button><button class="btn btn-primary">{{saving?'Saving…':'Save client'}}</button></div></form></AppModal><div v-if="error" class="fixed bottom-5 right-5 rounded-xl bg-rose-600 px-4 py-3 text-xs font-bold text-white shadow-xl">{{error}}</div></div></template>
<script setup lang="ts">import MoneyInput from '../../components/MoneyInput.vue';import {onMounted,ref} from 'vue';import {api,apiError} from '../../services/api';import {useConfirm} from '../../stores/confirm';import {useToast} from '../../stores/toast';import AppModal from '../../components/AppModal.vue';import StatusBadge from '../../components/StatusBadge.vue';const {ask:confirm}=useConfirm();const toast=useToast();const clients=ref<any[]>([]),search=ref(''),open=ref(false),editing=ref<any>(null),saving=ref(false),error=ref('');const blank=()=>({name:'',phone:'',email:'',contact_person:'',city:'',tin:'',vrn:'',credit_limit:0,credit_days:0,address:'',notes:'',is_active:true});const form=ref<any>(blank());function money(v:any){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(v||0))}async function load(){const {data}=await api.get('/clients',{params:{search:search.value,per_page:30}});clients.value=data.data}function openCreate(){editing.value=null;form.value=blank();error.value='';open.value=true}function edit(c:any){editing.value=c;form.value={...blank(),...c};error.value='';open.value=true}async function save(){saving.value=true;error.value='';try{if(editing.value)await api.put(`/clients/${editing.value.id}`,form.value);else await api.post('/clients',form.value);open.value=false;await load();toast.success(editing.value?'Client updated':'Client created', editing.value?'Changes saved successfully.':'Client was created successfully.')}catch(e){error.value=apiError(e);toast.error('Action failed', apiError(e))}finally{saving.value=false}}async function remove(c:any){if(!(await confirm({title:'Delete client?',message:`You are about to delete ${c.name}. Clients with transaction history must be deactivated instead.`,confirmText:'Delete',danger:true})))return;try{await api.delete(`/clients/${c.id}`);await load();toast.success('Client deleted', `${c.name} was deleted successfully.`)}catch(e){error.value=apiError(e);toast.error('Action failed', apiError(e))}}onMounted(load)</script>
